SELECT DATE_TRUNC('QUARTER', last_restock) AS quarter_start, CASE WHEN quantity >= 225 THEN 'HIGH' ELSE 'LOW' END AS quantity_tier, MIN(quantity) AS min_quantity, COUNT(DISTINCT product_id) AS distinct_product_ids, COUNT(DISTINCT store_id) AS distinct_store_ids, BIT_OR(quantity) AS quantity_bit_or, GROUPING_ID() AS grouping_level FROM inventory GROUP BY ROLLUP (DATE_TRUNC('QUARTER', last_restock), CASE WHEN quantity >= 225 THEN 'HIGH' ELSE 'LOW' END) HAVING COUNT(DISTINCT product_id) > 1 ORDER BY distinct_store_ids;
